/* Stage 1 (all 10 decoded screens) + player test art.
 *
 * Generated by tools/pack_stage_all.py and tools/gen_player_spr.py from
 * PC Engine track 2:
 *   stage1_all_maps.bin : 10 screens x 32x24 plane A entries (remapped tiles)
 *   stage1_all_tiles.bin: 1297 distinct 8x8 tiles converted to MD format
 *   stage1_all_pal.bin  : 64 VCE colours converted to MD CRAM words
 *   player_spr.bin      : engine test art (real character sprites not decoded yet)
 */

.section .rodata
#include <macros.s>

GLABEL res_stage1_all_tiles
.incbin "../res/gfx/stage1_all_tiles.bin"
.align 2

GLABEL res_stage1_all_pal
.byte 0
.byte 63
.incbin "../res/gfx/stage1_all_pal.bin"
.align 2

GLABEL res_stage1_all_maps
.incbin "../res/gfx/stage1_all_maps.bin"
.align 2

GLABEL res_player_spr
.incbin "../res/gfx/player_spr.bin"
.align 2
